WorkbenchSourcesPaginationQuery:
query WorkbenchSourcesPaginationQuery(
  $count: Int = 20
  $cursor: String
) {
  ...WorkbenchSources_sources_1G22uz
}

fragment WorkbenchSources_sources_1G22uz on Query {
  sources(first: $count, after: $cursor) {
    edges {
      cursor
      node {
        id
        sourceId
        namespace
        canonicalUri
        mediaType
        byteLength
        observedAt
        promotedSpanCount
        __typename
      }
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

